() => { 
  const event = new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true });
  document.dispatchEvent(event);
  document.body.dispatchEvent(event);
  return 'escape pressed';
}

() => { 
  // Try to find and click the rating button to close the dropdown
  const buttons = document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.includes('评分')) {
      btn.click();
      return 'clicked 评分 button';
    }
  }
  return 'not found';
}

() => { 
  // Find the rating dropdown div and click on the 评分不限 element to close
  const items = document.querySelectorAll('[role="menuitemradio"]');
  for (const item of items) {
    if (item.textContent.includes('评分不限')) {
      item.click();
      return 'clicked 评分不限';
    }
  }
  return 'not found, items: ' + items.length;
}

() => {
  // Find all place listings in the search results
  const resultItems = document.querySelectorAll('a[aria-label]');
  const places = [];
  for (const item of resultItems) {
    const ariaLabel = item.getAttribute('aria-label');
    if (ariaLabel && ariaLabel !== 'Google 应用' && !ariaLabel.includes('菜单') && !ariaLabel.includes('关闭')) {
      // Get parent container to find rating
      const parent = item.closest('[role="article"]') || item.parentElement;
      const parentText = parent ? parent.textContent : '';
      // Try to find rating
      const ratingMatch = parentText.match(/(\d+\.\d+)\s*\(/);
      places.push({
        name: ariaLabel,
        text: parentText.substring(0, 200),
        rating: ratingMatch ? ratingMatch[1] : null
      });
    }
  }
  return places.slice(0, 15);
}

() => {
  // Find close buttons or overlay and dismiss
  const closeButtons = document.querySelectorAll('button[aria-label="关闭"], button[aria-label="Close"]');
  for (const btn of closeButtons) {
    btn.click();
    return 'closed one button';
  }
  // Also try pressing escape on body
  return 'close buttons: ' + closeButtons.length;
}

() => {
  // Find all place listings in the search results panel
  const allText = document.querySelector('[role='main']') ? document.querySelector('[role='main']').textContent : 'no main';
  return allText.substring(0, 3000);
}

() => {
  const allText = document.querySelector('[role="main"]') ? document.querySelector('[role="main"]').textContent : 'no main';
  return allText.substring(0, 3000);
}

() => {
  // Find any overlay/modal
  const overlay = document.querySelector('[role="dialog"]');
  if (overlay) {
    const closeBtn = overlay.querySelector('button[aria-label="关闭"], button[aria-label="Close"]');
    if (closeBtn) {
      closeBtn.click();
      return 'overlay closed';
    }
    return 'overlay found but no close button';
  }
  return 'no overlay';
}

