() => {
  // Find all anchors that look like place listings
  const anchors = document.querySelectorAll("a[aria-label]");
  const places = [];
  for (const a of anchors) {
    const label = a.getAttribute("aria-label");
    if (label && !label.includes("关闭") && !label.includes("Close") && !label.includes("菜单") && label.length > 2) {
      const parent = a.closest("div");
      let text = "";
      let curr = parent;
      for (let i = 0; i < 5 && curr; i++) {
        text = curr.textContent || "";
        if (text.length > 30) break;
        curr = curr.parentElement;
      }
      places.push({
        name: label,
        text: text.substring(0, 300)
      });
    }
  }
  return places.slice(0, 10);
}

() => {
  // Find the overlay dialog
  const dialogs = document.querySelectorAll('[role="dialog"]');
  const result = [];
  for (const d of dialogs) {
    result.push({
      ariaLabel: d.getAttribute('aria-label'),
      role: d.getAttribute('role'),
      text: (d.textContent || '').substring(0, 200)
    });
  }
  return result;
}

() => {
  // Find all rating spans
  const ratings = document.querySelectorAll('span[role="img"]');
  const result = [];
  for (const r of ratings) {
    const label = r.getAttribute('aria-label');
    if (label && (label.includes('星级') || label.includes('stars'))) {
      result.push({
        label: label,
        text: r.textContent
      });
    }
  }
  return result;
}

() => {
  // Get the text content of the results panel
  const panels = document.querySelectorAll('[role="main"], [role="region"]');
  for (const p of panels) {
    const text = p.textContent || '';
    if (text.includes('Jake')) {
      // Found the results panel - extract rating info
      const matches = text.match(/(\d+\.\d+)\((\d+)\)/g) || [];
      return {
        panelText: text.substring(0, 1500),
        ratings: matches
      };
    }
  }
  return 'no results panel found';
}

() => {
  // Find all visible fixed/sticky/absolute elements that could be overlays
  const candidates = document.querySelectorAll('div');
  const overlays = [];
  for (const d of candidates) {
    const style = window.getComputedStyle(d);
    const zIndex = parseInt(style.zIndex);
    if (zIndex > 100 && style.position === 'fixed' && d.offsetWidth > 200 && d.offsetHeight > 200) {
      overlays.push({
        zIndex: zIndex,
        id: d.id,
        className: d.className.substring(0, 100),
        role: d.getAttribute('role'),
        text: (d.textContent || '').substring(0, 100)
      });
    }
  }
  return overlays;
}

() => {
